"""Polynomial-time reduction from Vertex Cover to Clique.

A set S is a vertex cover of G iff V \\ S is a clique in the complement
graph complement(G).  Hence G has a vertex cover of size at most k iff
complement(G) has a clique of size at least n - k.

So reduce maps (G, k) to (complement(G), n - k).
"""

from __future__ import annotations

from typing import Any


def reduce(instance: dict[str, Any]) -> dict[str, Any]:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]

    existing = set()
    for u, v in edges:
        existing.add((u, v) if u < v else (v, u))

    complement = []
    for u in range(n):
        for v in range(u + 1, n):
            if (u, v) not in existing:
                complement.append([u, v])

    return {"n": n, "edges": complement, "k": n - k}
EOF
cat > solvers.py <<'EOF'
"""Brute-force solvers for Vertex Cover and Clique (small instances)."""

from itertools import combinations


def vertex_cover_yes(instance):
    n = instance["n"]
    edges = [tuple(e) for e in instance["edges"]]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    for size in range(0, k + 1):
        for subset in combinations(range(n), size):
            s = set(subset)
            if all(u in s or v in s for u, v in edges):
                return True
    return False


def clique_yes(instance):
    n = instance["n"]
    edges = {frozenset(e) for e in instance["edges"]}
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    for subset in combinations(range(n), k):
        if all(frozenset((u, v)) in edges for u, v in combinations(subset, 2)):
            return True
    return False
EOF
